maximum_subarray.optimal:
current = nums[0], best = nums[0]
for each index i from 1 to n - 1:
    if current < 0:
        current = nums[i]   (a negative running sum is dead weight: restart here)
    else:
        current = current + nums[i]
    if current > best: best = current
return best

jump_game.brute:
can_reach_end(i):
    if i >= n - 1: return true
    for each step from 1 to nums[i]:
        if can_reach_end(i + step): return true
    return false
return can_reach_end(0)

jump_game.optimal:
reach = 0   (furthest index we can stand on so far)
for each index i:
    if i > reach: return false   (beyond the frontier: we never got here)
    if i + nums[i] > reach: reach = i + nums[i]
return true

partition_labels.brute:
sizes = [], start = 0
for each index i:
    part_letters = set of letters in s[start..i]
    appears_later = false
    for each j from i + 1 to n - 1:
        if s[j] is in part_letters: appears_later = true, break
    if not appears_later:   (no letter of the part shows up again: cut here)
        append i - start + 1 to sizes
        start = i + 1
return sizes

partition_labels.optimal:
last = empty dict
for each index i: last[s[i]] = i   (final index of every letter)
sizes = [], start = 0, end = 0
for each index i:
    if last[s[i]] > end: end = last[s[i]]
    if i == end:   (nothing inside points further right: cut here)
        append end - start + 1 to sizes
        start = i + 1
return sizes

single_number.brute:
for each x in nums:
    count = 0
    for each y in nums:
        if y == x: count = count + 1
    if count == 1: return x
return -1

missing_number.brute:
for each candidate from 0 to n:
    found = false
    for each x in nums:
        if x == candidate: found = true, break
    if not found: return candidate
return -1

rotate_image.brute:
rotated = n x n matrix of zeros
for each row r:
    for each column c:
        rotated[c][n - 1 - r] = matrix[r][c]
for each row r:
    matrix[r] = rotated[r]

rotate_image.optimal:
for each row r:
    for each column c > r:
        swap matrix[r][c] and matrix[c][r]   (transpose)
for each row in matrix:
    reverse the row   (transpose + horizontal flip = 90 degrees clockwise)

set_matrix_zeroes.brute:
snapshot = copy of every row of matrix
for each row r:
    for each column c:
        if snapshot[r][c] == 0:
            set every cell in row r of matrix to 0
            set every cell in column c of matrix to 0

set_matrix_zeroes.optimal:
first_col_zero = false
for each row r: if matrix[r][0] == 0: first_col_zero = true   (column 0 needs its own flag)
for each row r:
    for each column c from 1 to cols - 1:
        if matrix[r][c] == 0: matrix[r][0] = 0, matrix[0][c] = 0
for each row r from 1 to rows - 1:
    for each column c from 1 to cols - 1:
        if matrix[r][0] == 0 or matrix[0][c] == 0: matrix[r][c] = 0
if matrix[0][0] == 0: set every cell in row 0 to 0
if first_col_zero: set every cell in column 0 to 0
